(()=>{
  const M=ScheduleModel,$=s=>document.querySelector(s),key='course-schedule-v1';let courses=M.samples.map(c=>({...c})),day=0,selected=null,timer;
  try{const raw=localStorage.getItem(key);if(raw!==null){const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error();const accepted=[];for(const c of parsed){if(typeof c.id!=='string'||accepted.some(x=>x.id===c.id)||M.validate(c,accepted))throw Error();accepted.push(c);}courses=accepted;}}catch{$('#storage-warning').hidden=false;$('#storage-warning').textContent='无法读取已保存的课表，当前显示示例数据。';}
  function save(){try{localStorage.setItem(key,JSON.stringify(courses));}catch{$('#storage-warning').hidden=false;$('#storage-warning').textContent='浏览器存储不可用，当前修改只能保留到页面关闭。';}}
  function text(tag,value,className){const e=document.createElement(tag);e.textContent=value;if(className)e.className=className;return e;}
  function notify(value){$('#toast').textContent=value;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
  function teachers(){const old=$('#teacher').value;$('#teacher').replaceChildren(new Option('全部教师',''));[...new Set(courses.map(c=>c.teacher))].sort().forEach(t=>$('#teacher').add(new Option(t,t)));if([...$('#teacher').options].some(o=>o.value===old))$('#teacher').value=old;}
  function card(c){const b=text('button','','course tone-'+(Array.from(c.name).reduce((a,x)=>a+x.codePointAt(0),0)%5));b.type='button';b.append(text('strong',c.name),text('small',c.teacher+' · '+c.room),text('small',M.days[c.day-1]+' · 第 '+c.start+'–'+c.end+' 节'));b.setAttribute('aria-label',`${c.name}，${M.days[c.day-1]}第${c.start}到${c.end}节，${c.teacher}，${c.room}，查看详情`);b.onclick=()=>detail(c.id);return b;}
  function render(){const results=M.filter(courses,{day,teacher:$('#teacher').value,query:$('#query').value});$('#count').textContent=results.length+' 门课程';document.querySelectorAll('.days button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.day)===day)));$('#schedule').replaceChildren();$('#empty').hidden=results.length>0;if(!results.length)return;
    if(day){const list=text('div','','day-list');results.forEach(c=>list.append(card(c)));$('#schedule').append(list);return;}
    const scroll=text('div','','table-scroll'),table=document.createElement('table'),head=document.createElement('thead'),row=document.createElement('tr');row.append(text('th','节次'));M.days.forEach(d=>{const th=text('th',d);th.scope='col';row.append(th);});head.append(row);table.append(head);table.setAttribute('aria-label','每周课程表');const body=document.createElement('tbody');
    for(let p=1;p<=12;p++){const tr=document.createElement('tr');const label=text('th',String(p).padStart(2,'0'),'period');label.scope='row';tr.append(label);for(let d=1;d<=7;d++){const c=results.find(x=>x.day===d&&x.start<=p&&x.end>=p);if(c&&c.start!==p)continue;const cell=document.createElement('td');if(c){cell.rowSpan=c.end-c.start+1;cell.append(card(c));}tr.append(cell);}body.append(tr);}table.append(body);scroll.append(table);$('#schedule').append(scroll);
  }
  [0,1,2,3,4,5,6,7].forEach(d=>{const b=text('button',d?M.days[d-1]:'整周');b.dataset.day=d;b.onclick=()=>{day=d;render();};$('.days').append(b);});
  M.days.forEach((d,i)=>$('#form-day').add(new Option(d,i+1)));for(let i=1;i<=12;i++){$('#form-start').add(new Option('第 '+i+' 节',i));$('#form-end').add(new Option('第 '+i+' 节',i));}
  $('#add-course').onclick=()=>{$('#course-form').reset();$('#form-day').value=day||1;$('#form-end').value=2;$('#form-error').textContent='';$('#editor').showModal();};
  document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
  $('#course-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),c={id:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random(),name:f.get('name').trim(),teacher:f.get('teacher').trim(),room:f.get('room').trim(),day:Number(f.get('day')),start:Number(f.get('start')),end:Number(f.get('end'))};const error=M.validate(c,courses);$('#form-error').textContent=error;if(error)return;courses.push(c);save();teachers();day=c.day;$('#teacher').value='';$('#query').value='';render();$('#editor').close();notify('课程已添加');};
  function detail(id){selected=id;const c=courses.find(x=>x.id===id);$('#detail-title').textContent=c.name;$('#detail-fields').replaceChildren();[['星期',M.days[c.day-1]],['节次',`第 ${c.start}–${c.end} 节`],['教师',c.teacher],['教室',c.room]].forEach(([k,v])=>$('#detail-fields').append(text('dt',k),text('dd',v)));$('#delete-confirm').hidden=true;$('#detail-actions').hidden=false;$('#detail').showModal();}
  $('#delete-course').onclick=()=>{$('#delete-confirm').hidden=false;$('#detail-actions').hidden=true;$('#cancel-delete').focus();};$('#cancel-delete').onclick=()=>{$('#delete-confirm').hidden=true;$('#detail-actions').hidden=false;$('#delete-course').focus();};$('#confirm-delete').onclick=()=>{courses=courses.filter(c=>c.id!==selected);save();teachers();render();$('#detail').close();notify('课程已删除');};
  $('#query').oninput=render;$('#teacher').onchange=render;$('#clear').onclick=()=>{day=0;$('#query').value='';$('#teacher').value='';render();};
  teachers();render();
  if(document.modelContext?.registerTool){
    try{Promise.resolve(document.modelContext.registerTool({name:'filter_courses',description:'按星期、教师或关键词筛选当前课程表，同时更新页面。',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:0,maximum:7},teacher:{type:'string'},query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['day','teacher','query'].includes(k))||(input.day!==undefined&&(!Number.isInteger(input.day)||input.day<0||input.day>7))||(input.teacher!==undefined&&typeof input.teacher!=='string')||(input.query!==undefined&&typeof input.query!=='string'))throw Error('筛选参数无效');if(input.teacher&&!courses.some(c=>c.teacher===input.teacher))throw Error('教师不存在');day=input.day??0;$('#teacher').value=input.teacher??'';$('#query').value=input.query??'';render();return {courses:M.filter(courses,{day,teacher:$('#teacher').value,query:$('#query').value})};}})).catch(()=>{});}catch{}
  }
})();
